import re

def parse_duration(s: str) -> int:
    """
    Convert a human-readable duration string like '1h 30m' into total seconds.
    Supported units: h (hours), m (minutes), s (seconds).

    Also supports:
    - Bare numbers as seconds
    - Decimal values
    - Raises ValueError for invalid input that contains no valid parts
    """
    if not s or not s.strip():
        return 0

    s = s.strip()

    # Pattern to match number (int or float) followed by optional unit
    # This handles '1.5h', '30m', '45s', and bare '45'
    pattern = r'(\d+\.?\d*)\s*([hHmMsS])?'
    matches = re.findall(pattern, s)

    if not matches:
        raise ValueError(f"Invalid duration string: {s}")

    total_seconds = 0
    for value_str, unit in matches:
        try:
            value = float(value_str)
        except ValueError:
            continue

        if unit:
            unit_lower = unit.lower()
            if unit_lower == 'h':
                total_seconds += value * 3600
            elif unit_lower == 'm':
                total_seconds += value * 60
            elif unit_lower == 's':
                total_seconds += value
        else:
            # Bare number treated as seconds
            total_seconds += value

    return int(total_seconds)
